383	/** 番号の入った円を足す。(x, y) は円を囲む四角の左上の角、d は直径 (インチ)。 */
384	export function badge(
385	  s: SlideFigure,
386	  n: number | string,
387	  x: number,
388	  y: number,
389	  d: number,
390	  o: BadgeOptions = {},
391	): void {
392	  s.elements.push({
393	    kind: "shape",
394	    shape: "ellipse",
395	    x,
396	    y,
397	    w: d,
398	    h: d,
399	    fill: { color: o.fill ?? "accent1", transparency: 0 },
400	    outline: null,
401	    text: {
402	      paragraphs: toParagraphs(String(n), {
403	        fontSize: o.fontSize ?? 12,
404	        bold: true,
405	        color: "lt1",
406	      }),
407	      align: "center",
408	      valign: "middle",
409	      margin: toMargin(0),
410	      paraSpaceAfter: 0,
411	    },
412	    name: null,
413	  });
414	}
