/** 突き合わせの結果に、不一致が 1 つでもあるか。 */
export function hasMismatch(m: KeyMismatch): boolean {
  return m.outlineOnly.length > 0 || m.deckOnly.length > 0 || m.deckDuplicates.length > 0;
}

